 private async Task InitializeObservationSchemaAsync(SqliteConnection connection,CancellationToken cancellationToken)
 {
  await using(SqliteCommand schema=connection.CreateCommand()){schema.CommandText=ObservationSchema;await schema.ExecuteNonQueryAsync(cancellationToken);}
  await using SqliteTransaction transaction=connection.BeginTransaction(deferred:false);
  var columns=new HashSet<string>(StringComparer.OrdinalIgnoreCase);
  await using(SqliteCommand inspect=Command(connection,transaction,"SELECT name FROM pragma_table_info('TruthSampleBatches');"))
  await using(SqliteDataReader reader=await inspect.ExecuteReaderAsync(cancellationToken)){while(await reader.ReadAsync(cancellationToken))columns.Add(reader.GetString(0));}
  foreach((string Name,string Definition) missing in new[]{("ScenarioId","TEXT NULL"),("CanonicalBindingRequestJson","TEXT NULL"),("CanonicalSamplingOptionsJson","TEXT NULL")})
  {
   if(columns.Contains(missing.Name))continue;
   await using SqliteCommand alter=Command(connection,transaction,$"ALTER TABLE TruthSampleBatches ADD COLUMN {missing.Name} {missing.Definition};");await alter.ExecuteNonQueryAsync(cancellationToken);
  }
  await transaction.CommitAsync(cancellationToken);
 }
