 private static bool StrictTruthSequence(IReadOnlyList<TruthSampleDto> samples){double prior=-1;foreach(var x in samples){if(x.MeasuredDepthM<=prior||!ReservoirSamplingClient.IsPhysicallyValid(x))return false;prior=x.MeasuredDepthM;}return true;}
 private static bool LowerHash(string value)=>value.Length==64&&value.All(c=>c is >= '0' and <= '9' or >= 'a' and <= 'f'); private const string ObservationSchema="""
 CREATE TABLE IF NOT EXISTS SurveyArtifacts(SurveyArtifactId TEXT PRIMARY KEY,RunId TEXT NOT NULL UNIQUE,ExecutionId TEXT NOT NULL UNIQUE,ModelVersion TEXT NOT NULL,CalibrationVersion TEXT NOT NULL,OptionsHash TEXT NOT NULL,CanonicalInputJson TEXT NOT NULL,InputHash TEXT NOT NULL,CanonicalOutputJson TEXT NOT NULL,OutputHash TEXT NOT NULL,SurveyPathJson TEXT NOT NULL,PathHash TEXT NOT NULL,StationCount INTEGER NOT NULL,StartSimulatedSeconds REAL NOT NULL,EndSimulatedSeconds REAL NOT NULL,CreatedUtc TEXT NOT NULL,FOREIGN KEY(RunId)REFERENCES Runs(RunId));
 CREATE TRIGGER IF NOT EXISTS TR_SurveyArtifacts_NoUpdate BEFORE UPDATE ON SurveyArtifacts BEGIN SELECT RAISE(ABORT,'Survey artifacts are immutable');END;CREATE TRIGGER IF NOT EXISTS TR_SurveyArtifacts_NoDelete BEFORE DELETE ON SurveyArtifacts BEGIN SELECT RAISE(ABORT,'Survey artifacts are immutable');END;
 CREATE TABLE IF NOT EXISTS TruthSampleBatches(BatchId TEXT PRIMARY KEY,RunId TEXT NOT NULL UNIQUE,ScenarioId TEXT NOT NULL,WorldId TEXT NOT NULL,StageAPathBindingId TEXT NOT NULL,PropertySetVersion TEXT NOT NULL,SampleCount INTEGER NOT NULL,BindingHash TEXT NOT NULL,CanonicalBindingJson TEXT NOT NULL,CanonicalBindingRequestJson TEXT NOT NULL,BindingRequestHash TEXT NOT NULL,CanonicalSamplingOptionsJson TEXT NOT NULL,SamplingOptionsHash TEXT NOT NULL,CanonicalResponseJson TEXT NOT NULL,ResponseHash TEXT NOT NULL,CreatedUtc TEXT NOT NULL,FOREIGN KEY(RunId)REFERENCES Runs(RunId));
 CREATE TRIGGER IF NOT EXISTS TR_TruthSampleBatches_NoUpdate BEFORE UPDATE ON TruthSampleBatches BEGIN SELECT RAISE(ABORT,'Truth sample batches are immutable');END;CREATE TRIGGER IF NOT EXISTS TR_TruthSampleBatches_NoDelete BEFORE DELETE ON TruthSampleBatches BEGIN SELECT RAISE(ABORT,'Truth sample batches are immutable');END;
 """;
